/**
 * LegacyBank — hostile legacy core-banking simulator.
 * Data model + tenant configurations.
 *
 * Deliberately hostile surface properties (see REPORT.md):
 *  - ASP.NET WebForms-style autogenerated control names (ctl00$ContentPlaceHolder1$...)
 *  - no semantic classes, no data-testid, table-based layout, <frameset> shell
 *  - two tenants running the SAME vendor product, configured differently
 */

export interface TenantConfig {
  id: string;
  pathPrefix: string;
  institutionName: string;
  vendorProduct: string;
  themeColor: string;
  /** Labels that differ between tenants of the same product — drives variant overrides. */
  labels: {
    signInButton: string;
    memberIdLabel: string;
    searchButton: string;
    membersNavLink: string;
    resultsHeading: string;
    openSubAccountLink: string;
    confirmButton: string;
  };
}

