export interface Account {
  type: 'Savings' | 'Checking' | 'Money Market';
  number: string;
  balance: string;
}

export interface Member {
  id: string;
  firstName: string;
  lastName: string;
  status: 'Active' | 'Locked';
  since: string;
  accounts: Account[];
  locked?: boolean;
}

